#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/linker/sections.h>
#include <zephyr/linker/iterable_sections.h>

/* Struct that will be packed into a section */
struct iterable_test_struct {
	int val;
};

/*
 * ROM based section.
 * These are const so will be placed in ROM.
 */
#define ROM_TEST_VAL_1 1
#define ROM_TEST_VAL_2 2
#define ROM_TEST_VAL_3 4
#define ROM_TEST_VAL_4 8
#define ROM_EXPECT (ROM_TEST_VAL_1 + ROM_TEST_VAL_2 + ROM_TEST_VAL_3 + ROM_TEST_VAL_4)

STRUCT_SECTION_START(iterable_test_struct, rom_structs);
static const Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, rom_struct_1) = {
	.val = ROM_TEST_VAL_1,
};
static const Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, rom_struct_2) = {
	.val = ROM_TEST_VAL_2,
};
static const Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, rom_struct_3) = {
	.val = ROM_TEST_VAL_3,
};
static const Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, rom_struct_4) = {
	.val = ROM_TEST_VAL_4,
};
STRUCT_SECTION_END(iterable_test_struct, rom_structs);

/*
 * RAM based section.
 * These are not const so will be placed in RAM.
 */
#define RAM_TEST_VAL_1 16
#define RAM_TEST_VAL_2 32
#define RAM_TEST_VAL_3 64
#define RAM_TEST_VAL_4 128
#define RAM_EXPECT (RAM_TEST_VAL_1 + RAM_TEST_VAL_2 + RAM_TEST_VAL_3 + RAM_TEST_VAL_4)

STRUCT_SECTION_START(iterable_test_struct, ram_structs);
static Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, ram_struct_1) = {
	.val = RAM_TEST_VAL_1,
};
static Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, ram_struct_2) = {
	.val = RAM_TEST_VAL_2,
};
static Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, ram_struct_3) = {
	.val = RAM_TEST_VAL_3,
};
static Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, ram_struct_4) = {
	.val = RAM_TEST_VAL_4,
};
/*
 * Do not use STRUCT_SECTION_END here as it creates a const stop element.
 * This would be placed in a different section to the non-const ram elements,
 * causing the iteration to fail.
 */
static Z_STRUCT_SECTION_ITERABLE(iterable_test_struct, __stop_ram_structs);


static void iterable_sections_test_rom(void)
{
	int out = 0;

	STRUCT_SECTION_FOREACH(iterable_test_struct, rom_structs, s) {
		out += s->val;
	}
	zassert_equal(out, ROM_EXPECT, "iterable_sections_test_rom: (%d not equal to %d)",
		      out, ROM_EXPECT);
}

static void iterable_sections_test_ram(void)
{
	int out = 0;

	STRUCT_SECTION_FOREACH(iterable_test_struct, ram_structs, s) {
		out += s->val;
	}
	zassert_equal(out, RAM_EXPECT, "iterable_sections_test_ram: (%d not equal to %d)",
		      out, RAM_EXPECT);
}

ZTEST(iterable_sections, test_rom)
{
	iterable_sections_test_rom();
}

ZTEST(iterable_sections, test_ram)
{
	iterable_sections_test_ram();
}

ZTEST_SUITE(iterable_sections, NULL, NULL, NULL, NULL, NULL);
